// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { ConfirmDialog } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Overlays/ConfirmDialog)

figma.connect(ConfirmDialog, FIGMA_NODE_URL, {
  props: {
    intent: figma.enum('intent', { 'primary': 'primary', 'destructive': 'destructive' }),
    label: figma.string('label'),
    description: figma.string('description'),
  },
  example: ({ label, intent, description }) => (
    <ConfirmDialog intent={intent} description={description}>{label}</ConfirmDialog>
  ),
});
